import { graphql } from "@keystone-6/core";
import type { Context, ProviderAuthorizationStatusType, ProviderCredentialStatusType, ProviderStatusType } from ".keystone/types";
import { permissions } from "../access";
import { assertPracticeRecord, bounded, evidenceHash, requireActorPractice, validIdempotencyKey } from "../workflowAuth";
import { serializableWorkflow } from "./serializableWorkflow";

type Result = { success: boolean; recordId: string | null; evidenceHash: string | null; error: string | null };
const denied = { success: false, recordId: null, evidenceHash: null };
function authority(context: Context) {
  const actor = requireActorPractice(context, permissions.canManageClinical, "Clinical authority-pack access is required");
  if (!permissions.canManagePractice({ session: context.session as any })) throw new Error("Practice-owner approval is required for authority packs");
  return actor;
}
function failure(error: unknown): Result { return { ...denied, error: error instanceof Error ? error.message : "Authority-pack workflow failed" }; }

export async function registerProviderCredentialTransaction(context: Context, args: {
  providerId: string; locationId?: string | null; licenseType: string; licenseNumber: string; jurisdiction: string; effectiveFrom: string; expiresAt: string;
  verificationSource: string; evidenceReference: string; scopeEvidence: unknown; supervisionRequired: boolean; supervisorId?: string | null; protocolVersion: string; idempotencyKey: string;
}): Promise<Result> {
  let actor; try { actor = authority(context); } catch (error) { return failure(error); }
  const from = new Date(args.effectiveFrom); const expires = new Date(args.expiresAt);
  if (!validIdempotencyKey(args.idempotencyKey) || !args.licenseType.trim() || !args.licenseNumber.trim() || !args.jurisdiction.trim() || !args.verificationSource.trim()
    || !args.evidenceReference.trim() || !args.protocolVersion.trim() || Number.isNaN(from.getTime()) || Number.isNaN(expires.getTime()) || expires <= from || (args.supervisionRequired && !args.supervisorId)) return { ...denied, error: "Credential evidence is incomplete" };
  try {
    const [provider] = await Promise.all([assertPracticeRecord(context, "Provider", args.providerId, "id practice { id } user { id }"), args.locationId ? assertPracticeRecord(context, "Location", args.locationId) : Promise.resolve(null), args.supervisorId ? assertPracticeRecord(context, "Provider", args.supervisorId) : Promise.resolve(null)]);
    if (provider.user?.id === actor.actorId) throw new Error("A provider cannot verify their own credential");
    const evidence = { ...args, scopeEvidenceHash: evidenceHash(args.scopeEvidence), actorId: actor.actorId, recordedAt: new Date().toISOString() }; const hash = evidenceHash(evidence);
    return await serializableWorkflow(context, "medspa-provider-credential", [`provider:${args.providerId}`, `idempotency:${args.idempotencyKey}`], async tx => { const sudo = tx.sudo(); const existing = (await sudo.query.ProviderCredential.findMany({ where: { practice: { id: { equals: actor.practiceId } }, idempotencyKey: { equals: args.idempotencyKey } }, take: 1, query: "id scopeEvidenceHash" }))[0]; if (existing) return { success: true, recordId: existing.id, evidenceHash: existing.scopeEvidenceHash, error: null }; const record = await sudo.query.ProviderCredential.createOne({ data: {
      practice: { connect: { id: actor.practiceId } }, provider: { connect: { id: args.providerId } }, location: args.locationId ? { connect: { id: args.locationId } } : undefined,
      licenseType: args.licenseType.trim(), licenseNumber: args.licenseNumber.trim(), jurisdiction: args.jurisdiction.trim(), status: "verified", effectiveFrom: from.toISOString(), expiresAt: expires.toISOString(), verifiedAt: evidence.recordedAt,
      verificationSource: args.verificationSource.trim(), primarySourceVerified: true, supervisionRequired: args.supervisionRequired, supervisor: args.supervisorId ? { connect: { id: args.supervisorId } } : undefined,
      scopeEvidenceHash: evidence.scopeEvidenceHash, evidenceReference: args.evidenceReference.trim(), protocolVersion: args.protocolVersion.trim(), idempotencyKey: args.idempotencyKey,
    }, query: "id scopeEvidenceHash" }); return { success: true, recordId: record.id, evidenceHash: hash, error: null }; });
  } catch (error) { return failure(error); }
}

export async function configureProviderAuthorizationTransaction(context: Context, args: {
  providerId: string; credentialId: string; locationId: string; serviceId: string; requiredSupervisorId?: string | null; supervisionRequired: boolean; supervisionMode?: string | null;
  effectiveFrom: string; effectiveTo?: string | null; policyVersion: string; evidenceLabel: string; evidenceReference: string; authorityEvidence: unknown; idempotencyKey: string;
}): Promise<Result> {
  let actor; try { actor = authority(context); } catch (error) { return failure(error); }
  const from = new Date(args.effectiveFrom); const to = args.effectiveTo ? new Date(args.effectiveTo) : null;
  if (!validIdempotencyKey(args.idempotencyKey) || !args.policyVersion.trim() || !args.evidenceLabel.trim() || !args.evidenceReference.trim() || Number.isNaN(from.getTime()) || (to && (Number.isNaN(to.getTime()) || to <= from)) || (args.supervisionRequired && !args.requiredSupervisorId)) return { ...denied, error: "Provider authorization pack is incomplete" };
  try {
    const [provider, credential, location, _service, supervisor] = await Promise.all([assertPracticeRecord(context, "Provider", args.providerId, "id practice { id } user { id }"), assertPracticeRecord(context, "ProviderCredential", args.credentialId, "id practice { id } status effectiveFrom expiresAt provider { id } location { id }"), assertPracticeRecord(context, "Location", args.locationId), assertPracticeRecord(context, "Service", args.serviceId), args.requiredSupervisorId ? assertPracticeRecord(context, "Provider", args.requiredSupervisorId, "id practice { id } user { id }") : Promise.resolve(null)]);
    if (provider.user?.id === actor.actorId || supervisor?.user?.id === actor.actorId) throw new Error("Authority approval must be independent of performer and required supervisor");
    if (credential.provider?.id !== provider.id || credential.status !== "verified" || new Date(credential.effectiveFrom) > from || new Date(credential.expiresAt) <= from || (credential.location?.id && credential.location.id !== location.id)) throw new Error("Credential does not authorize this provider, location, and effective time");
    const authorityEvidenceHash = evidenceHash(args.authorityEvidence);
    return await serializableWorkflow(context, "medspa-provider-authorization", [`provider:${args.providerId}`, `service:${args.serviceId}`, `location:${args.locationId}`, `idempotency:${args.idempotencyKey}`], async tx => { const sudo = tx.sudo(); const existing = (await sudo.query.ProviderAuthorization.findMany({ where: { practice: { id: { equals: actor.practiceId } }, idempotencyKey: { equals: args.idempotencyKey } }, take: 1, query: "id authorityEvidenceHash" }))[0]; if (existing) return { success: true, recordId: existing.id, evidenceHash: existing.authorityEvidenceHash, error: null }; const record = await sudo.query.ProviderAuthorization.createOne({ data: {
      practice: { connect: { id: actor.practiceId } }, provider: { connect: { id: args.providerId } }, credential: { connect: { id: args.credentialId } }, location: { connect: { id: args.locationId } }, service: { connect: { id: args.serviceId } },
      requiredSupervisor: args.requiredSupervisorId ? { connect: { id: args.requiredSupervisorId } } : undefined, status: "active", effectiveFrom: from.toISOString(), effectiveTo: to ? to.toISOString() : undefined,
      supervisionRequired: args.supervisionRequired, supervisionMode: args.supervisionMode || "", policyVersion: args.policyVersion.trim(), authorityEvidenceHash, idempotencyKey: args.idempotencyKey, evidenceLabel: args.evidenceLabel.trim(), evidenceReference: args.evidenceReference.trim(),
    }, query: "id authorityEvidenceHash" }); return { success: true, recordId: record.id, evidenceHash: record.authorityEvidenceHash, error: null }; });
  } catch (error) { return failure(error); }
}

export async function publishConsentTemplateTransaction(context: Context, args: {
  serviceId: string; jurisdiction: string; language: string; version: string; content: unknown; effectiveFrom: string; effectiveUntil?: string | null; supersedesId?: string | null; idempotencyKey: string;
}): Promise<Result> {
  let actor; try { actor = authority(context); } catch (error) { return failure(error); }
  const from = new Date(args.effectiveFrom); const until = args.effectiveUntil ? new Date(args.effectiveUntil) : null;
  if (!validIdempotencyKey(args.idempotencyKey) || !args.jurisdiction.trim() || !args.language.trim() || !args.version.trim() || Number.isNaN(from.getTime()) || (until && (Number.isNaN(until.getTime()) || until <= from))) return { ...denied, error: "Consent template pack is incomplete" };
  try {
    const [_service, prior] = await Promise.all([assertPracticeRecord(context, "Service", args.serviceId), args.supersedesId ? assertPracticeRecord(context, "ConsentTemplateVersion", args.supersedesId, "id practice { id } service { id } effectiveFrom effectiveUntil supersededBy { id }") : Promise.resolve(null)]);
    if (prior && (prior.service?.id !== args.serviceId || prior.supersededBy?.id || (prior.effectiveUntil && new Date(prior.effectiveUntil) <= from))) throw new Error("Consent-template supersession is invalid");
    const contentHash = evidenceHash(args.content);
    return await serializableWorkflow(context, "medspa-consent-template", [`service:${args.serviceId}`, `idempotency:${args.idempotencyKey}`], async tx => {
      const sudo = tx.sudo(); const existing = (await sudo.query.ConsentTemplateVersion.findMany({ where: { practice: { id: { equals: actor.practiceId } }, idempotencyKey: { equals: args.idempotencyKey } }, take: 1, query: "id contentHash" }))[0]; if (existing) return { success: true, recordId: existing.id, evidenceHash: existing.contentHash, error: null };
      const record = await sudo.query.ConsentTemplateVersion.createOne({ data: { practice: { connect: { id: actor.practiceId } }, service: { connect: { id: args.serviceId } }, jurisdiction: args.jurisdiction.trim(), language: args.language.trim(), version: args.version.trim(), contentSnapshot: bounded(args.content), contentHash, effectiveFrom: from.toISOString(), effectiveUntil: until ? until.toISOString() : undefined, supersedes: args.supersedesId ? { connect: { id: args.supersedesId } } : undefined, idempotencyKey: args.idempotencyKey }, query: "id contentHash" });
      if (prior) await sudo.query.ConsentTemplateVersion.updateOne({ where: { id: prior.id }, data: { effectiveUntil: from.toISOString() }, query: "id" });
      return { success: true, recordId: record.id, evidenceHash: record.contentHash, error: null };
    });
  } catch (error) { return failure(error); }
}

export async function transitionProviderAuthorityTransaction(context: Context, args: { targetType: "provider" | "credential" | "authorization"; targetId: string; action: "activate" | "suspend" | "revoke"; reason: string; idempotencyKey: string }): Promise<Result> {
  if (!new Set(["provider","credential","authorization"]).has(args.targetType) || !new Set(["activate","suspend","revoke"]).has(args.action)) return { ...denied, error: "Authority transition is invalid" };
  let actor; try { actor = authority(context); await assertPracticeRecord(context, args.targetType === "provider" ? "Provider" : args.targetType === "credential" ? "ProviderCredential" : "ProviderAuthorization", args.targetId); } catch (error) { return failure(error) }
  if (!validIdempotencyKey(args.idempotencyKey) || !args.reason.trim() || args.reason.length > 1_000) return { ...denied, error: "Authority transition evidence is invalid" }
  try { return await serializableWorkflow(context, "medspa-provider-authority-transition", [`${args.targetType}:${args.targetId}`, `idempotency:${args.idempotencyKey}`], async tx => { const sudo = tx.sudo(); const priorEvent = (await sudo.query.AuditEvent.findMany({ where: { practice: { id: { equals: actor.practiceId } }, correlationId: { equals: args.idempotencyKey }, action: { equals: "provider_authority.transitioned" } }, take: 1, query: "resourceId evidenceHash" }))[0]; if (priorEvent) return { success: true, recordId: priorEvent.resourceId, evidenceHash: priorEvent.evidenceHash, error: null }; let fromStatus = "", toStatus = "";
    if (args.targetType === "provider") { const provider = await sudo.query.Provider.findOne({ where: { id: args.targetId }, query: "id status user { id } credentials { id status effectiveFrom expiresAt primarySourceVerified } authorizations { id status effectiveFrom effectiveTo }" }); if (!provider) throw new Error("Provider not found"); fromStatus = provider.status; if (args.action === "activate") { if (provider.user?.id === actor.actorId) throw new Error("A provider cannot independently activate their own profile"); const now = new Date(); const credential = provider.credentials.some((item: any) => item.status === "verified" && item.primarySourceVerified === true && new Date(item.effectiveFrom) <= now && new Date(item.expiresAt) > now); const authorization = provider.authorizations.some((item: any) => item.status === "active" && new Date(item.effectiveFrom) <= now && (!item.effectiveTo || new Date(item.effectiveTo) > now)); if (!credential || !authorization) throw new Error("Effective credential and service authorization are required"); toStatus = "active"; } else { toStatus = "inactive"; } const providerStatus: ProviderStatusType = toStatus === "active" ? "active" : "inactive"; await sudo.query.Provider.updateOne({ where: { id: provider.id }, data: { status: providerStatus, isActive: providerStatus === "active", isPublic: providerStatus === "active" ? undefined : false }, query: "id" });
    } else if (args.targetType === "credential") { const credential = await sudo.query.ProviderCredential.findOne({ where: { id: args.targetId }, query: "id status authorizations { id status }" }); if (!credential) throw new Error("Credential not found"); if (args.action === "activate") throw new Error("Credentials require fresh primary-source verification"); fromStatus = credential.status; toStatus = args.action === "revoke" ? "revoked" : "suspended"; const credentialStatus: ProviderCredentialStatusType = args.action === "revoke" ? "revoked" : "suspended"; await sudo.query.ProviderCredential.updateOne({ where: { id: credential.id }, data: { status: credentialStatus, primarySourceVerified: false }, query: "id" }); for (const authorization of credential.authorizations || []) if (authorization.status === "active") await sudo.query.ProviderAuthorization.updateOne({ where: { id: authorization.id }, data: { status: "suspended" }, query: "id" });
    } else { const authorization = await sudo.query.ProviderAuthorization.findOne({ where: { id: args.targetId }, query: "id status" }); if (!authorization) throw new Error("Authorization not found"); if (args.action === "activate") throw new Error("Authorization activation requires a new effective-dated pack"); fromStatus = authorization.status; toStatus = "suspended"; const authorizationStatus: ProviderAuthorizationStatusType = "suspended"; await sudo.query.ProviderAuthorization.updateOne({ where: { id: authorization.id }, data: { status: authorizationStatus }, query: "id" }); }
    const occurredAt = new Date().toISOString(), hash = evidenceHash({ ...args, fromStatus, toStatus, actorId: actor.actorId, occurredAt }); await sudo.query.AuditEvent.createOne({ data: { practice: { connect: { id: actor.practiceId } }, actor: { connect: { id: actor.actorId } }, action: "provider_authority.transitioned", resourceType: args.targetType, resourceId: args.targetId, correlationId: args.idempotencyKey, evidence: { fromStatus, toStatus, reason: args.reason.trim() }, evidenceHash: hash, occurredAt }, query: "id" }); return { success: true, recordId: args.targetId, evidenceHash: hash, error: null }; }); } catch (error) { return failure(error) }
}

const resultType = graphql.object<Result>()({ name: "AuthorityPackResult", fields: { success: graphql.field({ type: graphql.nonNull(graphql.Boolean) }), recordId: graphql.field({ type: graphql.ID }), evidenceHash: graphql.field({ type: graphql.String }), error: graphql.field({ type: graphql.String }) } });
const wrap = (fn: any, args: Record<string, any>) => graphql.field({ type: resultType, args, resolve(_s, values, context: Context) { return fn(context, values); } });
