import { graphql } from '@keystone-6/core'
import type { Context, FollowUpActionActionType, FollowUpActionRedFlagType } from '.keystone/types'
import { permissions } from '../access'
import { assertPracticeRecord, bounded, evidenceHash, requireActorPractice, validIdempotencyKey } from '../workflowAuth'
import { serializableWorkflow } from './serializableWorkflow'

type Result = { success: boolean; recordId: string | null; status: string | null; error: string | null }
const denied = { success: false, recordId: null, status: null }
const fail = (error: unknown): Result => ({ ...denied, error: error instanceof Error ? error.message : 'Follow-up workflow failed' })

export async function scheduleFollowUpTransaction(context: Context, args: { treatmentSessionId: string; assignedToId: string; dueAt: string; title: string; instructions: string; idempotencyKey: string }): Promise<Result> {
  let actor; try { actor = requireActorPractice(context, permissions.canManageClinical); await Promise.all([assertPracticeRecord(context, 'TreatmentSession', args.treatmentSessionId), assertPracticeRecord(context, 'User', args.assignedToId)]) } catch (error) { return fail(error) }
  const dueAt = new Date(args.dueAt); if (!validIdempotencyKey(args.idempotencyKey) || Number.isNaN(dueAt.getTime()) || dueAt <= new Date() || !args.title.trim()) return { ...denied, error: 'Follow-up schedule is invalid' }
  try { return await serializableWorkflow(context, 'medspa-follow-up-schedule', [`session:${args.treatmentSessionId}`, `idempotency:${args.idempotencyKey}`], async tx => { const sudo = tx.sudo(), existing = (await sudo.query.FollowUpAction.findMany({ where: { practice: { id: { equals: actor.practiceId } }, idempotencyKey: { equals: args.idempotencyKey } }, take: 1, query: 'task { id status }' }))[0]; if (existing?.task) return { success: true, recordId: existing.task.id, status: existing.task.status, error: null }; const session = await sudo.query.TreatmentSession.findOne({ where: { id: args.treatmentSessionId }, query: 'id client { id } appointment { id location { id } }' }); if (!session?.client || !session.appointment?.location) throw new Error('Treatment session is unavailable'); const occurredAt = new Date().toISOString(), hash = evidenceHash({ ...args, actorId: actor.actorId, occurredAt }); const task = await sudo.query.FollowUpTask.createOne({ data: { practice: { connect: { id: actor.practiceId } }, location: { connect: { id: session.appointment.location.id } }, client: { connect: { id: session.client.id } }, appointment: { connect: { id: session.appointment.id } }, treatmentSession: { connect: { id: session.id } }, assignedTo: { connect: { id: args.assignedToId } }, dueAt: dueAt.toISOString(), title: args.title.trim(), instructions: args.instructions.trim(), status: 'open' }, query: 'id status' }); await sudo.query.FollowUpAction.createOne({ data: { practice: { connect: { id: actor.practiceId } }, task: { connect: { id: task.id } }, actor: { connect: { id: actor.actorId } }, action: 'schedule', reason: 'Procedure-derived follow-up scheduled', evidence: { dueAt: dueAt.toISOString(), treatmentSessionId: session.id }, redFlag: 'none', evidenceHash: hash, occurredAt, idempotencyKey: args.idempotencyKey }, query: 'id' }); return { success: true, recordId: task.id, status: task.status, error: null } }) } catch (error) { return fail(error) }
}

export async function appendFollowUpActionTransaction(context: Context, args: { taskId: string; action: Exclude<FollowUpActionActionType, 'schedule'>; reason: string; evidence: unknown; redFlag: FollowUpActionRedFlagType; idempotencyKey: string }): Promise<Result> {
  let actor; try { actor = requireActorPractice(context, permissions.canManageClinical); await assertPracticeRecord(context, 'FollowUpTask', args.taskId) } catch (error) { return fail(error) }
  if (!validIdempotencyKey(args.idempotencyKey) || !['contact','patient_response','escalate','complete','cancel'].includes(args.action) || !['none','review','urgent'].includes(args.redFlag) || !args.reason.trim()) return { ...denied, error: 'Follow-up action is invalid' }
  try { return await serializableWorkflow(context, 'medspa-follow-up-action', [`task:${args.taskId}`, `idempotency:${args.idempotencyKey}`], async tx => { const sudo = tx.sudo(), existing = (await sudo.query.FollowUpAction.findMany({ where: { practice: { id: { equals: actor.practiceId } }, idempotencyKey: { equals: args.idempotencyKey } }, take: 1, query: 'task { id status }' }))[0]; if (existing?.task) { if (existing.task.id !== args.taskId) throw new Error('Idempotency key was already used'); return { success: true, recordId: existing.task.id, status: existing.task.status, error: null } } const task = await sudo.query.FollowUpTask.findOne({ where: { id: args.taskId }, query: 'id status' }); if (!task || ['completed','cancelled'].includes(task.status)) throw new Error('Follow-up is closed'); const occurredAt = new Date().toISOString(), status = args.action === 'complete' ? 'completed' : args.action === 'cancel' ? 'cancelled' : 'in_progress', hash = evidenceHash({ ...args, actorId: actor.actorId, occurredAt }); await sudo.query.FollowUpAction.createOne({ data: { practice: { connect: { id: actor.practiceId } }, task: { connect: { id: task.id } }, actor: { connect: { id: actor.actorId } }, action: args.action, reason: args.reason.trim(), evidence: bounded(args.evidence), redFlag: args.redFlag, evidenceHash: hash, occurredAt, idempotencyKey: args.idempotencyKey }, query: 'id' }); await sudo.query.FollowUpTask.updateOne({ where: { id: task.id }, data: { status, completedAt: status === 'completed' ? occurredAt : undefined }, query: 'id' }); return { success: true, recordId: task.id, status, error: null } }) } catch (error) { return fail(error) }
}

export async function submitFollowUpResponseTransaction(context: Context, args: { taskId: string; response: unknown; redFlag: FollowUpActionRedFlagType; idempotencyKey: string }): Promise<Result> {
  if (!context.session?.itemId || !validIdempotencyKey(args.idempotencyKey) || !['none','review','urgent'].includes(args.redFlag)) return { ...denied, error: 'Authenticated follow-up response is invalid' }
  try { const task = await assertPracticeRecord(context, 'FollowUpTask', args.taskId, 'id practice { id } client { user { id } }'); if (task.client?.user?.id !== context.session.itemId) throw new Error('Follow-up ownership could not be verified'); return await serializableWorkflow(context, 'medspa-follow-up-response', [`task:${args.taskId}`, `idempotency:${args.idempotencyKey}`], async tx => { const sudo = tx.sudo(), existing = (await sudo.query.FollowUpAction.findMany({ where: { practice: { id: { equals: task.practice.id } }, idempotencyKey: { equals: args.idempotencyKey } }, take: 1, query: 'task { id status }' }))[0]; if (existing?.task) { if (existing.task.id !== args.taskId) throw new Error('Idempotency key was already used'); return { success: true, recordId: existing.task.id, status: existing.task.status, error: null } } const current = await sudo.query.FollowUpTask.findOne({ where: { id: args.taskId }, query: 'id status' }); if (!current || ['completed','cancelled'].includes(current.status)) throw new Error('Follow-up is closed'); const occurredAt = new Date().toISOString(), hash = evidenceHash({ ...args, actorId: context.session!.itemId, occurredAt }); await sudo.query.FollowUpAction.createOne({ data: { practice: { connect: { id: task.practice.id } }, task: { connect: { id: task.id } }, actor: { connect: { id: context.session!.itemId } }, action: 'patient_response', reason: 'Authenticated patient response', evidence: bounded(args.response), redFlag: args.redFlag, evidenceHash: hash, occurredAt, idempotencyKey: args.idempotencyKey }, query: 'id' }); await sudo.query.FollowUpTask.updateOne({ where: { id: task.id }, data: { status: 'in_progress' }, query: 'id' }); return { success: true, recordId: task.id, status: 'in_progress', error: null } }) } catch (error) { return fail(error) }
}

const resultType = graphql.object<Result>()({ name: 'FollowUpWorkflowResult', fields: { success: graphql.field({ type: graphql.nonNull(graphql.Boolean) }), recordId: graphql.field({ type: graphql.ID }), status: graphql.field({ type: graphql.String }), error: graphql.field({ type: graphql.String }) } })
const wrap = (fn:any,args:any) => graphql.field({ type: resultType, args, resolve: (_s:any,values:any,context:Context) => fn(context,values) })
export const scheduleFollowUp = wrap(scheduleFollowUpTransaction,{ treatmentSessionId:graphql.arg({type:graphql.nonNull(graphql.ID)}), assignedToId:graphql.arg({type:graphql.nonNull(graphql.ID)}), dueAt:graphql.arg({type:graphql.nonNull(graphql.String)}), title:graphql.arg({type:graphql.nonNull(graphql.String)}), instructions:graphql.arg({type:graphql.nonNull(graphql.String)}), idempotencyKey:graphql.arg({type:graphql.nonNull(graphql.String)}) })
export const submitFollowUpResponse = wrap(submitFollowUpResponseTransaction,{ taskId:graphql.arg({type:graphql.nonNull(graphql.ID)}), response:graphql.arg({type:graphql.nonNull(graphql.JSON)}), redFlag:graphql.arg({type:graphql.nonNull(graphql.String)}), idempotencyKey:graphql.arg({type:graphql.nonNull(graphql.String)}) })
export const appendFollowUpAction = wrap(appendFollowUpActionTransaction,{ taskId:graphql.arg({type:graphql.nonNull(graphql.ID)}), action:graphql.arg({type:graphql.nonNull(graphql.String)}), reason:graphql.arg({type:graphql.nonNull(graphql.String)}), evidence:graphql.arg({type:graphql.nonNull(graphql.JSON)}), redFlag:graphql.arg({type:graphql.nonNull(graphql.String)}), idempotencyKey:graphql.arg({type:graphql.nonNull(graphql.String)}) })
