import { graphql } from '@keystone-6/core'
import type { ClinicalOrderActionActionType, ClinicalOrderStatusType, Context } from '.keystone/types'
import { permissions } from '../access'
import { assertActiveActor, assertPracticeRecord, assertProviderActor, bounded, evidenceHash, requireActorPractice, validIdempotencyKey } from '../workflowAuth'
import { serializableWorkflow } from './serializableWorkflow'

type Result = { success: boolean; recordId: string | null; evidenceHash: string | null; error: string | null }
const denied = { success: false, recordId: null, evidenceHash: null }
const fail = (error: unknown): Result => ({ ...denied, error: error instanceof Error ? error.message : 'Clinical record action failed' })

export async function transitionClinicalOrderTransaction(context: Context, args: { orderId: string; providerId: string; action: ClinicalOrderActionActionType; reason: string; evidence: unknown; idempotencyKey: string }): Promise<Result> {
  let actor; try { actor = requireActorPractice(context, permissions.canManageClinical); await Promise.all([assertPracticeRecord(context, 'ClinicalOrder', args.orderId), assertProviderActor(context, args.providerId, actor.actorId)]) } catch (error) { return fail(error) }
  const next: Record<ClinicalOrderActionActionType, ClinicalOrderStatusType> = { hold: 'held', release: 'active', partially_fulfill: 'partially_fulfilled', fulfill: 'fulfilled', revoke: 'revoked', expire: 'expired', enter_in_error: 'entered_in_error' }
  if (!next[args.action] || !validIdempotencyKey(args.idempotencyKey) || !args.reason.trim()) return { ...denied, error: 'Order action is invalid' }
  try { return await serializableWorkflow(context, 'medspa-clinical-order-action', [`order:${args.orderId}`, `idempotency:${args.idempotencyKey}`], async tx => {
    const sudo = tx.sudo(), existing = (await sudo.query.ClinicalOrderAction.findMany({ where: { practice: { id: { equals: actor.practiceId } }, idempotencyKey: { equals: args.idempotencyKey } }, take: 1, query: 'id evidenceHash order { id }' }))[0]
    if (existing) { if (existing.order?.id !== args.orderId) throw new Error('Idempotency key was already used'); return { success: true, recordId: args.orderId, evidenceHash: existing.evidenceHash, error: null } }
    const order = await sudo.query.ClinicalOrder.findOne({ where: { id: args.orderId }, query: 'id status' }); if (!order) throw new Error('Order not found')
    const allowed: Record<string,string[]> = { active: ['hold','partially_fulfill','fulfill','revoke','expire','enter_in_error'], held: ['release','revoke','expire','enter_in_error'], partially_fulfilled: ['hold','fulfill','revoke','expire','enter_in_error'] }; if (!allowed[order.status]?.includes(args.action)) throw new Error('Clinical order transition is invalid')
    const occurredAt = new Date().toISOString(), hash = evidenceHash({ ...args, fromStatus: order.status, toStatus: next[args.action], actorId: actor.actorId, occurredAt })
    await sudo.query.ClinicalOrderAction.createOne({ data: { practice: { connect: { id: actor.practiceId } }, order: { connect: { id: order.id } }, actor: { connect: { id: args.providerId } }, action: args.action, fromStatus: order.status, toStatus: next[args.action], reason: args.reason.trim(), evidence: bounded(args.evidence), evidenceHash: hash, occurredAt, idempotencyKey: args.idempotencyKey }, query: 'id' })
    await sudo.query.ClinicalOrder.updateOne({ where: { id: order.id }, data: { status: next[args.action] }, query: 'id' })
    return { success: true, recordId: order.id, evidenceHash: hash, error: null }
  }) } catch (error) { return fail(error) }
}

export async function withdrawTreatmentConsentTransaction(context: Context, args: { consentId: string; reason: string; idempotencyKey: string }): Promise<Result> {
  let actor; try { actor = await assertActiveActor(context); const consent = await assertPracticeRecord(context, 'ConsentRecord', args.consentId, 'id practice { id } client { user { id } }'); if (consent.client?.user?.id !== actor.actorId && !permissions.canManageClinical({ session: context.session as any })) throw new Error('Consent withdrawal ownership is not authorized') } catch (error) { return fail(error) }
  if (!validIdempotencyKey(args.idempotencyKey) || !args.reason.trim()) return { ...denied, error: 'Consent withdrawal evidence is invalid' }
  try { return await serializableWorkflow(context, 'medspa-consent-withdrawal', [`consent:${args.consentId}`, `idempotency:${args.idempotencyKey}`], async tx => {
    const sudo = tx.sudo(), existing = (await sudo.query.ConsentAction.findMany({ where: { practice: { id: { equals: actor.practiceId } }, idempotencyKey: { equals: args.idempotencyKey } }, take: 1, query: 'id evidenceHash consent { id }' }))[0]
    if (existing) { if (existing.consent?.id !== args.consentId) throw new Error('Idempotency key was already used'); return { success: true, recordId: args.consentId, evidenceHash: existing.evidenceHash, error: null } }
    const consent = await sudo.query.ConsentRecord.findOne({ where: { id: args.consentId }, query: 'id status' }); if (!consent || consent.status !== 'effective') throw new Error('Only effective consent can be withdrawn')
    const occurredAt = new Date().toISOString(), hash = evidenceHash({ ...args, actorId: actor.actorId, occurredAt })
    await sudo.query.ConsentAction.createOne({ data: { practice: { connect: { id: actor.practiceId } }, consent: { connect: { id: consent.id } }, actor: { connect: { id: actor.actorId } }, action: 'withdraw', fromStatus: consent.status, toStatus: 'withdrawn', reason: args.reason.trim(), evidence: { patientRequestRecorded: true }, evidenceHash: hash, occurredAt, idempotencyKey: args.idempotencyKey }, query: 'id' })
    await sudo.query.ConsentRecord.updateOne({ where: { id: consent.id }, data: { status: 'withdrawn', withdrawnAt: occurredAt }, query: 'id' })
    return { success: true, recordId: consent.id, evidenceHash: hash, error: null }
  }) } catch (error) { return fail(error) }
}

export async function appendSignedClinicalNoteTransaction(context: Context, args: { clientId: string; appointmentId?: string | null; providerId: string; type: string; content: string; supersedesId?: string | null; reason?: string | null; idempotencyKey: string }): Promise<Result> {
  let actor; try { actor = requireActorPractice(context, permissions.canManageClinical); const records = await Promise.all([assertPracticeRecord(context, 'Client', args.clientId), assertProviderActor(context, args.providerId, actor.actorId), args.appointmentId ? assertPracticeRecord(context, 'Appointment', args.appointmentId, 'id practice { id } client { id }') : null, args.supersedesId ? assertPracticeRecord(context, 'ClientNote', args.supersedesId, 'id practice { id } client { id } supersededBy { id }') : null]); if (records[2] && records[2].client?.id !== args.clientId) throw new Error('Appointment does not match the client'); if (records[3] && (records[3].client?.id !== args.clientId || records[3].supersededBy?.id)) throw new Error('Clinical note supersession is invalid') } catch (error) { return fail(error) }
  if (!validIdempotencyKey(args.idempotencyKey) || !args.type.trim() || !args.content.trim() || (args.supersedesId && !args.reason?.trim())) return { ...denied, error: 'Signed note evidence is invalid' }
  try { return await serializableWorkflow(context, 'medspa-clinical-note', [`client:${args.clientId}`, `idempotency:${args.idempotencyKey}`], async tx => { const sudo = tx.sudo(), existing = (await sudo.query.ClientNote.findMany({ where: { practice: { id: { equals: actor.practiceId } }, idempotencyKey: { equals: args.idempotencyKey } }, take: 1, query: 'id evidenceHash' }))[0]; if (existing) return { success: true, recordId: existing.id, evidenceHash: existing.evidenceHash, error: null }; const signedAt = new Date().toISOString(), hash = evidenceHash({ ...args, actorId: actor.actorId, signedAt }); const note = await sudo.query.ClientNote.createOne({ data: { practice: { connect: { id: actor.practiceId } }, client: { connect: { id: args.clientId } }, appointment: args.appointmentId ? { connect: { id: args.appointmentId } } : undefined, author: { connect: { id: actor.actorId } }, type: args.type.trim(), content: args.content.trim(), status: 'signed', signedAt, evidenceHash: hash, idempotencyKey: args.idempotencyKey, supersedes: args.supersedesId ? { connect: { id: args.supersedesId } } : undefined, lateEntryReason: args.reason?.trim() || null }, query: 'id evidenceHash' }); return { success: true, recordId: note.id, evidenceHash: note.evidenceHash, error: null } }) } catch (error) { return fail(error) }
}

const resultType = graphql.object<Result>()({ name: 'ClinicalRecordActionResult', fields: { success: graphql.field({ type: graphql.nonNull(graphql.Boolean) }), recordId: graphql.field({ type: graphql.ID }), evidenceHash: graphql.field({ type: graphql.String }), error: graphql.field({ type: graphql.String }) } })
const wrap = (fn:any,args:any) => graphql.field({ type: resultType, args, resolve: (_s:any,values:any,context:Context) => fn(context,values) })
export const transitionClinicalOrder = wrap(transitionClinicalOrderTransaction,{ orderId: graphql.arg({type:graphql.nonNull(graphql.ID)}), providerId: graphql.arg({type:graphql.nonNull(graphql.ID)}), action: graphql.arg({type:graphql.nonNull(graphql.String)}), reason: graphql.arg({type:graphql.nonNull(graphql.String)}), evidence: graphql.arg({type:graphql.nonNull(graphql.JSON)}), idempotencyKey: graphql.arg({type:graphql.nonNull(graphql.String)}) })
export const withdrawTreatmentConsent = wrap(withdrawTreatmentConsentTransaction,{ consentId: graphql.arg({type:graphql.nonNull(graphql.ID)}), reason: graphql.arg({type:graphql.nonNull(graphql.String)}), idempotencyKey: graphql.arg({type:graphql.nonNull(graphql.String)}) })
export const appendSignedClinicalNote = wrap(appendSignedClinicalNoteTransaction,{ clientId:graphql.arg({type:graphql.nonNull(graphql.ID)}), appointmentId:graphql.arg({type:graphql.ID}), providerId:graphql.arg({type:graphql.nonNull(graphql.ID)}), type:graphql.arg({type:graphql.nonNull(graphql.String)}), content:graphql.arg({type:graphql.nonNull(graphql.String)}), supersedesId:graphql.arg({type:graphql.ID}), reason:graphql.arg({type:graphql.String}), idempotencyKey:graphql.arg({type:graphql.nonNull(graphql.String)}) })
