import { graphql } from "@keystone-6/core"
import { permissions } from "../access"
import { assertActiveActor, assertPracticeRecord, requireActorPractice } from "../workflowAuth"

const ServiceCommission = graphql.object<{ serviceName:string; revenue:number; commission:number }>()({ name:"ServiceCommission", fields:{ serviceName:graphql.field({type:graphql.nonNull(graphql.String)}), revenue:graphql.field({type:graphql.nonNull(graphql.Float)}), commission:graphql.field({type:graphql.nonNull(graphql.Float)}) } })
const AppointmentCommission = graphql.object<{ appointmentId:string; date:string; clientName:string; services:any[]; totalRevenue:number; totalCommission:number }>()({ name:"AppointmentCommission", fields:{ appointmentId:graphql.field({type:graphql.nonNull(graphql.ID)}), date:graphql.field({type:graphql.nonNull(graphql.String)}), clientName:graphql.field({type:graphql.nonNull(graphql.String)}), services:graphql.field({type:graphql.nonNull(graphql.list(graphql.nonNull(ServiceCommission)))}), totalRevenue:graphql.field({type:graphql.nonNull(graphql.Float)}), totalCommission:graphql.field({type:graphql.nonNull(graphql.Float)}) } })
const CommissionResult=graphql.object<{providerId:string;providerName:string;startDate:string;endDate:string;commissionRate:number;appointments:any[];totalServiceRevenue:number;totalServiceCommission:number;appointmentCount:number}>()({name:"CommissionResult",fields:{providerId:graphql.field({type:graphql.nonNull(graphql.ID)}),providerName:graphql.field({type:graphql.nonNull(graphql.String)}),startDate:graphql.field({type:graphql.nonNull(graphql.String)}),endDate:graphql.field({type:graphql.nonNull(graphql.String)}),commissionRate:graphql.field({type:graphql.nonNull(graphql.Float)}),appointments:graphql.field({type:graphql.nonNull(graphql.list(graphql.nonNull(AppointmentCommission)))}),totalServiceRevenue:graphql.field({type:graphql.nonNull(graphql.Float)}),totalServiceCommission:graphql.field({type:graphql.nonNull(graphql.Float)}),appointmentCount:graphql.field({type:graphql.nonNull(graphql.Int)})}})

export const calculateCommission=graphql.field({type:CommissionResult,args:{providerId:graphql.arg({type:graphql.nonNull(graphql.ID)}),startDate:graphql.arg({type:graphql.nonNull(graphql.String)}),endDate:graphql.arg({type:graphql.nonNull(graphql.String)})},async resolve(_source,args,context:any){
  const actor=requireActorPractice(context,permissions.canManageFinance,"Authorized finance access is required");await assertActiveActor(context);const provider=await assertPracticeRecord(context,"Provider",args.providerId,"id practice { id } user { name }");const start=new Date(`${args.startDate}T00:00:00.000Z`),end=new Date(`${args.endDate}T23:59:59.999Z`);if(Number.isNaN(start.getTime())||Number.isNaN(end.getTime())||end<start)throw new Error("Commission date range is invalid");
  const rows=await context.sudo().query.Commission.findMany({where:{practice:{id:{equals:actor.practiceId}},provider:{id:{equals:provider.id}},createdAt:{gte:start.toISOString(),lte:end.toISOString()}},take:1000,orderBy:{createdAt:"asc"},query:"id saleAmount commissionRate commissionAmount createdAt service { name } payment { appointment { id startTime client { user { name } } } }"});
  const groups=new Map<string,any>();for(const item of rows as any[]){const appointment=item.payment?.appointment;const id=appointment?.id||`unlinked:${item.id}`;const current=groups.get(id)||{appointmentId:id,date:appointment?.startTime||item.createdAt,clientName:appointment?.client?.user?.name||"Client omitted",services:[],totalRevenue:0,totalCommission:0};current.services.push({serviceName:item.service?.name||"Settled service",revenue:Number(item.saleAmount||0)/100,commission:Number(item.commissionAmount||0)/100});current.totalRevenue+=Number(item.saleAmount||0)/100;current.totalCommission+=Number(item.commissionAmount||0)/100;groups.set(id,current);}
  const appointments=[...groups.values()];const revenue=rows.reduce((sum:number,item:any)=>sum+Number(item.saleAmount||0),0)/100;const commission=rows.reduce((sum:number,item:any)=>sum+Number(item.commissionAmount||0),0)/100;return{providerId:provider.id,providerName:provider.user?.name||"Provider",startDate:args.startDate,endDate:args.endDate,commissionRate:revenue?commission/revenue:0,appointments,totalServiceRevenue:revenue,totalServiceCommission:commission,appointmentCount:appointments.length};
}})
