import { createHash, randomBytes } from 'node:crypto'
import { graphql } from '@keystone-6/core'
import type { Context, ProviderRoleType } from '.keystone/types'
import { permissions } from '../access'
import { assertActiveActor, assertPracticeRecord, requireActorPractice, validIdempotencyKey } from '../workflowAuth'
import { serializableWorkflow } from './serializableWorkflow'
import { capabilitiesWithinGrantAuthority, capabilityKeys, type CapabilityKey } from '../roleGrantPolicy'

const isCapabilityKey = (key: string): key is CapabilityKey => capabilityKeys.some(capability => capability === key)
const providerRoles = ['provider', 'esthetician', 'nurse', 'physician', 'assistant'] as const satisfies readonly ProviderRoleType[]
const isProviderRole = (value: string): value is ProviderRoleType => providerRoles.some(role => role === value)
const tokenHash = (token: string) => createHash('sha256').update(token).digest('hex')
type Result = { success: boolean; recordId: string | null; token: string | null; error: string | null }
const denied = (error: string): Result => ({ success: false, recordId: null, token: null, error })

export async function upsertAccessRoleTransaction(context: Context, args: { roleId?: string | null; name: string; capabilities: unknown; idempotencyKey: string }): Promise<Result> {
  let actor; try { actor = { ...requireActorPractice(context, permissions.canManageRoles), role: (await assertActiveActor(context)).role }; } catch (error) { return denied(error instanceof Error ? error.message : 'Role authority is required') }
  if (!validIdempotencyKey(args.idempotencyKey) || !args.name.trim() || args.name.length > 120 || !args.capabilities || typeof args.capabilities !== 'object' || Array.isArray(args.capabilities)) return denied('Access-role evidence is invalid')
  const source = args.capabilities as Record<string, unknown>; if (Object.keys(source).some(key => !isCapabilityKey(key) || typeof source[key] !== 'boolean')) return denied('Access-role capabilities are invalid')
  const capabilities: Record<CapabilityKey, boolean> = {
    canManagePeople: source.canManagePeople === true, canManageRoles: source.canManageRoles === true, canAccessDashboard: source.canAccessDashboard === true,
    canManageOnboarding: source.canManageOnboarding === true, canManagePractice: source.canManagePractice === true, canSchedule: source.canSchedule === true,
    canReadClients: source.canReadClients === true, canManageClinical: source.canManageClinical === true, canManageSensitiveRecords: source.canManageSensitiveRecords === true,
    canManageInventory: source.canManageInventory === true, canManageFinance: source.canManageFinance === true, canManageCommunications: source.canManageCommunications === true,
    canViewReports: source.canViewReports === true, canManageIntegrations: source.canManageIntegrations === true,
  }
  if (!capabilitiesWithinGrantAuthority(capabilities, actor.role)) return denied('You cannot grant capabilities you do not hold')
  const data = { name: args.name.trim(), practice: { connect: { id: actor.practiceId } }, ...capabilities }
  try { return await serializableWorkflow(context, 'medspa-access-role', [`idempotency:${args.idempotencyKey}`, ...(args.roleId ? [`role:${args.roleId}`] : [])], async tx => { const sudo = tx.sudo(); const prior = (await sudo.query.AuditEvent.findMany({ where: { practice: { id: { equals: actor.practiceId } }, correlationId: { equals: args.idempotencyKey }, action: { equals: 'access_role.upserted' } }, take: 1, query: 'resourceId' }))[0]; if (prior) return { success: true, recordId: prior.resourceId, token: null, error: null }; if (args.roleId) { const current = await sudo.query.Role.findOne({ where: { id: args.roleId }, query: 'id practice { id } assignedTo { id } canManagePeople canManageRoles canAccessDashboard canManageOnboarding canManagePractice canSchedule canReadClients canManageClinical canManageSensitiveRecords canManageInventory canManageFinance canManageCommunications canViewReports canManageIntegrations' }); if (!current || current.practice?.id !== actor.practiceId) throw new Error('Role not found'); if (current.assignedTo?.some((user: any) => user.id === actor.actorId)) throw new Error('You cannot edit a role assigned to your own account'); if (!capabilitiesWithinGrantAuthority(current, actor.role)) throw new Error('You cannot edit a role with capabilities you do not hold'); } const role = args.roleId ? await sudo.query.Role.updateOne({ where: { id: args.roleId }, data, query: 'id' }) : await sudo.query.Role.createOne({ data, query: 'id' }); const occurredAt = new Date().toISOString(), hash = tokenHash(JSON.stringify({ roleId: role.id, name: args.name, source, actorId: actor.actorId, occurredAt })); await sudo.query.AuditEvent.createOne({ data: { practice: { connect: { id: actor.practiceId } }, actor: { connect: { id: actor.actorId } }, action: 'access_role.upserted', resourceType: 'Role', resourceId: role.id, correlationId: args.idempotencyKey, evidence: { name: args.name, capabilities }, evidenceHash: hash, occurredAt }, query: 'id' }); return { success: true, recordId: role.id, token: null, error: null } }); } catch (error) { return denied(error instanceof Error ? error.message : 'Access role failed') }
}

export async function inviteStaffTransaction(context: Context, args: { email: string; roleId: string; locationIds?: readonly string[] | null; expiresInHours: number; idempotencyKey: string }): Promise<Result> {
  let actor; try { actor = { ...requireActorPractice(context, permissions.canManageRoles), role: (await assertActiveActor(context)).role }; await Promise.all([assertPracticeRecord(context, 'Role', args.roleId), ...(args.locationIds || []).map(id => assertPracticeRecord(context, 'Location', id))]); } catch (error) { return denied(error instanceof Error ? error.message : 'Role authority is required') }
  const email = args.email.trim().toLowerCase(); if (!validIdempotencyKey(args.idempotencyKey) || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email) || !Number.isInteger(args.expiresInHours) || args.expiresInHours < 1 || args.expiresInHours > 168 || (args.locationIds?.length || 0) > 100) return denied('Staff invitation is invalid')
  const invitedRole = await context.sudo().query.Role.findOne({ where: { id: args.roleId }, query: 'id practice { id } canManagePeople canManageRoles canAccessDashboard canManageOnboarding canManagePractice canSchedule canReadClients canManageClinical canManageSensitiveRecords canManageInventory canManageFinance canManageCommunications canViewReports canManageIntegrations' })
  if (!invitedRole || invitedRole.practice?.id !== actor.practiceId || !capabilitiesWithinGrantAuthority(invitedRole, actor.role)) return denied('You cannot assign a role with capabilities you do not hold')
  const token = randomBytes(32).toString('base64url'), hash = tokenHash(token), expiresAt = new Date(Date.now() + args.expiresInHours * 3_600_000).toISOString()
  try { return await serializableWorkflow(context, 'medspa-staff-invitation', [`email:${email}`, `idempotency:${args.idempotencyKey}`], async tx => { const sudo = tx.sudo(); const existing = (await sudo.query.StaffInvitation.findMany({ where: { practice: { id: { equals: actor.practiceId } }, idempotencyKey: { equals: args.idempotencyKey } }, take: 1, query: 'id' }))[0]; if (existing) return { success: true, recordId: existing.id, token: null, error: null }; const users = await sudo.query.User.findMany({ where: { email: { equals: email } }, take: 1, query: 'id' }); if (users.length) throw new Error('A user with this email already exists'); const invitation = await sudo.query.StaffInvitation.createOne({ data: { practice: { connect: { id: actor.practiceId } }, email, role: { connect: { id: args.roleId } }, locations: args.locationIds?.length ? { connect: args.locationIds.map(id => ({ id })) } : undefined, invitedBy: { connect: { id: actor.actorId } }, tokenHash: hash, status: 'pending', expiresAt, idempotencyKey: args.idempotencyKey }, query: 'id' }); return { success: true, recordId: invitation.id, token, error: null } }); } catch (error) { return denied(error instanceof Error ? error.message : 'Staff invitation failed') }
}

export async function acceptStaffInvitationTransaction(context: Context, args: { token: string; name: string; password: string }): Promise<Result> {
  if (context.session?.itemId || args.token.length < 32 || !args.name.trim() || args.name.length > 120 || args.password.length < 12 || args.password.length > 200) return denied('Invitation acceptance is invalid')
  const hash = tokenHash(args.token)
  try { return await serializableWorkflow(context, 'medspa-staff-invitation-accept', [`token:${hash}`], async tx => { const sudo = tx.sudo(); const invitation = (await sudo.query.StaffInvitation.findMany({ where: { tokenHash: { equals: hash } }, take: 1, query: `id email status expiresAt practice { id } role { id practice { id } canManagePeople canManageRoles canAccessDashboard canManageOnboarding canManagePractice canSchedule canReadClients canManageClinical canManageSensitiveRecords canManageInventory canManageFinance canManageCommunications canViewReports canManageIntegrations } locations { id practice { id } } invitedBy { id status name email practice { id } locations { id } role { id name canManagePeople canManageRoles canAccessDashboard canManageOnboarding canManagePractice canSchedule canReadClients canManageClinical canManageSensitiveRecords canManageInventory canManageFinance canManageCommunications canViewReports canManageIntegrations } }` }))[0]; if (!invitation || invitation.status !== 'pending' || new Date(invitation.expiresAt) <= new Date()) throw new Error('Invitation is invalid or expired'); if (invitation.role?.practice?.id !== invitation.practice?.id || invitation.locations.some((location: any) => location.practice?.id !== invitation.practice.id)) throw new Error('Invitation scope is invalid'); const inviter = invitation.invitedBy; if (!inviter || inviter.status !== 'active' || inviter.practice?.id !== invitation.practice.id || inviter.role?.canManagePeople !== true || inviter.role?.canManageRoles !== true || !capabilitiesWithinGrantAuthority(invitation.role, inviter.role)) throw new Error('Inviting authority is no longer active or cannot grant this role'); const syntheticSession = { itemId: inviter.id, listKey: 'User', data: { name: inviter.name, email: inviter.email, status: inviter.status, practice: { id: inviter.practice.id }, locations: inviter.locations || [], role: inviter.role } } as any; const scoped = tx.withSession(syntheticSession).sudo(); const user = await scoped.query.User.createOne({ data: { name: args.name.trim(), email: invitation.email, password: args.password, status: 'active', practice: { connect: { id: invitation.practice.id } }, role: { connect: { id: invitation.role.id } }, locations: invitation.locations.length ? { connect: invitation.locations.map((location: any) => ({ id: location.id })) } : undefined }, query: 'id' }); await scoped.query.StaffInvitation.updateOne({ where: { id: invitation.id }, data: { status: 'accepted', acceptedUser: { connect: { id: user.id } }, acceptedAt: new Date().toISOString(), tokenHash: tokenHash(randomBytes(32).toString('base64url')) }, query: 'id' }); return { success: true, recordId: user.id, token: null, error: null } }); } catch { return denied('Invitation is invalid or expired') }
}

export async function createProviderProfileTransaction(context: Context, args: { userId: string; role: ProviderRoleType; title?: string | null; locationIds: string[]; idempotencyKey: string }): Promise<Result> {
  let actor; try { actor = requireActorPractice(context, permissions.canManagePeople); const records = await Promise.all([assertPracticeRecord(context, 'User', args.userId, 'id status practice { id } providerProfile { id }'), ...args.locationIds.map(id => assertPracticeRecord(context, 'Location', id))]); if (records[0].status !== 'active' || records[0].providerProfile?.id) throw new Error('Provider profile is unavailable'); } catch (error) { return denied(error instanceof Error ? error.message : 'People authority is required') }
  if (!validIdempotencyKey(args.idempotencyKey) || !isProviderRole(args.role) || args.locationIds.length < 1 || args.locationIds.length > 100) return denied('Provider profile input is invalid')
  try { return await serializableWorkflow(context, 'medspa-provider-profile', [`user:${args.userId}`, `idempotency:${args.idempotencyKey}`], async tx => { const sudo = tx.sudo(); const prior = (await sudo.query.AuditEvent.findMany({ where: { practice: { id: { equals: actor.practiceId } }, correlationId: { equals: args.idempotencyKey }, action: { equals: 'provider_profile.created' } }, take: 1, query: 'resourceId' }))[0]; if (prior) return { success: true, recordId: prior.resourceId, token: null, error: null }; const provider = await sudo.query.Provider.createOne({ data: { practice: { connect: { id: actor.practiceId } }, user: { connect: { id: args.userId } }, role: args.role, title: args.title?.trim() || '', status: 'inactive', isActive: false, isPublic: false, locations: { connect: args.locationIds.map(id => ({ id })) } }, query: 'id' }); const occurredAt = new Date().toISOString(), hash = tokenHash(JSON.stringify({ providerId: provider.id, userId: args.userId, role: args.role, actorId: actor.actorId, occurredAt })); await sudo.query.AuditEvent.createOne({ data: { practice: { connect: { id: actor.practiceId } }, actor: { connect: { id: actor.actorId } }, action: 'provider_profile.created', resourceType: 'Provider', resourceId: provider.id, correlationId: args.idempotencyKey, evidence: { userId: args.userId, role: args.role, locationIds: args.locationIds, initialStatus: 'inactive' }, evidenceHash: hash, occurredAt }, query: 'id' }); return { success: true, recordId: provider.id, token: null, error: null } }); } catch (error) { return denied(error instanceof Error ? error.message : 'Provider profile failed') }
}

const resultType = graphql.object<Result>()({ name: 'StaffAccessWorkflowResult', fields: { success: graphql.field({ type: graphql.nonNull(graphql.Boolean) }), recordId: graphql.field({ type: graphql.ID }), token: graphql.field({ type: graphql.String }), error: graphql.field({ type: graphql.String }) } })
export const upsertAccessRole = graphql.field({ type: resultType, args: { roleId: graphql.arg({ type: graphql.ID }), name: graphql.arg({ type: graphql.nonNull(graphql.String) }), capabilities: graphql.arg({ type: graphql.nonNull(graphql.JSON) }), idempotencyKey: graphql.arg({ type: graphql.nonNull(graphql.String) }) }, resolve: (_s,args,context:Context) => upsertAccessRoleTransaction(context,args) })
export const inviteStaff = graphql.field({ type: resultType, args: { email: graphql.arg({ type: graphql.nonNull(graphql.String) }), roleId: graphql.arg({ type: graphql.nonNull(graphql.ID) }), locationIds: graphql.arg({ type: graphql.list(graphql.nonNull(graphql.ID)) }), expiresInHours: graphql.arg({ type: graphql.nonNull(graphql.Int) }), idempotencyKey: graphql.arg({ type: graphql.nonNull(graphql.String) }) }, resolve: (_s,args,context:Context) => inviteStaffTransaction(context,args) })
export const acceptStaffInvitation = graphql.field({ type: resultType, args: { token: graphql.arg({ type: graphql.nonNull(graphql.String) }), name: graphql.arg({ type: graphql.nonNull(graphql.String) }), password: graphql.arg({ type: graphql.nonNull(graphql.String) }) }, resolve: (_s,args,context:Context) => acceptStaffInvitationTransaction(context,args) })
export const createProviderProfile = graphql.field({ type: resultType, args: { userId: graphql.arg({ type: graphql.nonNull(graphql.ID) }), role: graphql.arg({ type: graphql.nonNull(graphql.String) }), title: graphql.arg({ type: graphql.String }), locationIds: graphql.arg({ type: graphql.nonNull(graphql.list(graphql.nonNull(graphql.ID))) }), idempotencyKey: graphql.arg({ type: graphql.nonNull(graphql.String) }) }, resolve: (_s,args,context:Context) => {
  if (!isProviderRole(args.role)) return Promise.resolve(denied('Provider profile input is invalid'))
  return createProviderProfileTransaction(context, { userId: args.userId, role: args.role, title: args.title, locationIds: args.locationIds, idempotencyKey: args.idempotencyKey })
} })
